import asyncdispatch, httpclient, json, math, times, uri

type Semaphore = ref object
  count: int
  max: int

proc newSemaphore(max: int): Semaphore =
  result = Semaphore(count: max, max: max)

proc acquire(s: Semaphore) {.async.} =
  while true:
    if s.count > 0:
      dec s.count
      return
    await sleepAsync(10)

proc release(s: Semaphore) {.async.} =
  inc s.count

proc fetchWithRetry(client: AsyncHttpClient, url: string, sem: Semaphore, maxRetries = 3): Future[JsonNode] {.async.} =
  await sem.acquire()
  var attempt = 0
  while true:
    try:
      let resp = await client.get(url)
      let body = await resp.body
      await sem.release()
      return parseJson(body)
    except CatchableError:
      inc attempt
      if attempt > maxRetries:
        await sem.release()
        raise
      await sleepAsync(int(pow(2.0, float(attempt)) * 1000))

