import asyncdispatch, httpclient, strutils, math, os

proc downloadWithProgress(url: string, destPath: string) {.async.} =
  let client = newAsyncHttpClient()
  let headResp = await client.request(url, HttpHead)
  var totalSize = 0
  if headResp.headers.hasKey("Content-Length"):
    totalSize = parseInt(headResp.headers["Content-Length"])

  let resp = await client.request(url, HttpGet)
  var file = open(destPath, fmWrite)
  var downloadedSize = 0

  while true:
    let (hasData, chunk) = await resp.bodyStream.read()
    if not hasData: break
    file.write(chunk)
    downloadedSize += chunk.len

    if totalSize > 0:
      let percentage = (downloadedSize.float / totalSize.float * 100.0).round(2)
      echo "Downloaded ", downloadedSize, " of ", totalSize, " bytes (", percentage, "%)"
    else:
      echo "Downloaded ", downloadedSize, " bytes"

  file.close()
  client.close()
  echo "Download complete: ", destPath

when isMainModule:
