type AsyncQueue[T] = ref object
  items: seq[T]

proc newAsyncQueue[T](): AsyncQueue[T] =
  AsyncQueue[T](items: @[])

proc push[T](q: AsyncQueue[T], item: T) {.async.} =
  q.items.add(item)

proc pop[T](q: AsyncQueue[T]): Future[T] {.async.} =
  while true:
    if q.items.len > 0:
      let item = q.items[0]
      q.items.delete(0)
      return item
    await sleepAsync(10)

proc worker(id: int, inQueue: AsyncQueue[string], outQueue: AsyncQueue[int]) {.async.} =
  while true:
    let filePath = await inQueue.pop()
    if filePath == "DONE":
      break

    echo "Worker ", id, " processing ", filePath
    await sleepAsync(100) # Simulate I/O bound work
    await outQueue.push(filePath.len)

proc master() {.async.} =
  let inQ = newAsyncQueue[string]()
  let outQ = newAsyncQueue[int]()

  for i in 1..3:
    asyncCheck worker(i, inQ, outQ)

  let files = @["file1.txt", "file2.csv", "document.pdf", "image.png"]
  for f in files:
    await inQ.push(f)

  for i in 1..3:
    await inQ.push("DONE")

  var totalLengths = 0
  for i in 1..files.len:
    let len = await outQ.pop()
    totalLengths += len

  echo "Total path length processed: ", totalLengths

when isMainModule:
  waitFor master()

