type
  CircuitState = enum Closed, Open, HalfOpen
  CircuitBreaker = ref object
    state: CircuitState
    failureCount: int
    failureThreshold: int
    resetTimeoutSecs: int
    lastFailureTime: Time

proc newCircuitBreaker(threshold, timeout: int): CircuitBreaker =
  CircuitBreaker(state: Closed, failureCount: 0, failureThreshold: threshold, resetTimeoutSecs: timeout)

proc execute[T](cb: CircuitBreaker, action: proc(): Future[T] {.gcsafe.}): Future[T] {.async.} =
  if cb.state == Open:
    if getTime() - cb.lastFailureTime > initDuration(seconds = cb.resetTimeoutSecs):
      cb.state = HalfOpen
    else:
      raise newException(CatchableError, "Circuit breaker is OPEN. Request rejected.")

  try:
    let result = await action()
    if cb.state == HalfOpen or cb.state == Closed:
      cb.failureCount = 0
      cb.state = Closed
    return result
  except CatchableError as e:
    cb.failureCount.inc
    cb.lastFailureTime = getTime()
    if cb.failureCount >= cb.failureThreshold:
      cb.state = Open
    raise e

