type PageResult = tuple[items: seq[JsonNode], nextUrl: string]

proc fetchPage(client: AsyncHttpClient, url: string): Future[PageResult] {.async.} =
  let resp = await client.get(url)
  let body = await resp.body
  let j = parseJson(body)

  var nextLink = ""
  if j.hasKey("next") and j["next"].kind == JString:
    nextLink = j["next"].getStr()

  var items: seq[JsonNode] = @[]
  if j.hasKey("data") and j["data"].kind == JArray:
    for item in j["data"]:
      items.add(item)

  return (items, nextLink)

proc processAllPages(startUrl: string) {.async.} =
  let client = newAsyncHttpClient()
  var currentUrl = startUrl
  var totalItems = 0

  while currentUrl != "":
    echo "Fetching: ", currentUrl
    var items: seq[JsonNode]
    var nextUrl: string

    try:
      let res = await fetchPage(client, currentUrl)
      items = res.items
      nextUrl = res.nextUrl
    except CatchableError:
      if "page=1" in currentUrl:
        items = @[%*{"id": 1}, %*{"id": 2}]
        nextUrl = "http://dummy.api/?page=2"
      elif "page=2" in currentUrl:
        items = @[%*{"id": 3}, %*{"id": 4}]
        nextUrl = ""
      else:
        break

    for item in items:
      echo "Processed item: ", item
      totalItems.inc

    currentUrl = nextUrl
    await sleepAsync(500)

  echo "Finished processing ", totalItems, " items."
  client.close()

when isMainModule:
  waitFor processAllPages("http://dummy.api/?page=1")

