proc handleBinaryConnection(client: AsyncSocket) {.async.} =
  try:
    while true:
      var headerStr = await client.recv(4)
      if headerStr.len != 4: break

      var msgLen: int32
      copyMem(addr msgLen, addr headerStr[0], 4)

      var payload = await client.recv(msgLen.int)
      if payload.len != msgLen.int: break

      echo "Received message of length ", msgLen, ": ", payload

      var respMsg = "ACK: " & payload
      var respLen = int32(respMsg.len)
      var outHeader = newString(4)
      copyMem(addr outHeader[0], addr respLen, 4)

      await client.send(outHeader & respMsg)
  except CatchableError as e:
    echo "Connection error: ", e.msg
  finally:
    client.close()

