var kvStore {.threadvar.}: Table[string, string]
kvStore = initTable[string, string]()

proc processLineCommand(client: AsyncSocket) {.async.} =
  defer: client.close()
  try:
    while true:
      let line = await client.recvLine()
      if line == "": break

      let parts = line.splitWhitespace()
      if parts.len == 0: continue

      let cmd = parts[0].toUpperAscii()
      if cmd == "GET" and parts.len == 2:
        if kvStore.hasKey(parts[1]):
          await client.send("+" & kvStore[parts[1]] & "\r\n")
        else:
          await client.send("$-1\r\n")
      elif cmd == "SET" and parts.len >= 3:
        let key = parts[1]
        let val = parts[2..^1].join(" ")
        kvStore[key] = val
        await client.send("+OK\r\n")
      elif cmd == "QUIT":
        await client.send("+BYE\r\n")
        break
      else:
        await client.send("-ERR unknown command\r\n")
  except CatchableError:
    discard

