import asynchttpserver, asyncdispatch, httpclient

proc proxyHandler(req: Request) {.async, gcsafe.} =
  let upstreamUrl = "http://httpbin.org" & req.url.path & (if req.url.query != "": "?" & req.url.query else: "")
  echo "Proxying request to: ", upstreamUrl

  let client = newAsyncHttpClient()

  var proxyHeaders = newHttpHeaders()
  for k, v in req.headers.pairs:
    if k != "host" and k != "connection":
      proxyHeaders.add(k, v)

  try:
    let upstreamResp = await client.request(upstreamUrl, req.reqMethod, body = req.body, headers = proxyHeaders)
    let bodyData = await upstreamResp.body

    var respHeaders = newHttpHeaders()
    for k, v in upstreamResp.headers.pairs:
      respHeaders.add(k, v)

    await req.respond(upstreamResp.code, bodyData, respHeaders)
  except CatchableError as e:
    await req.respond(Http502, "Bad Gateway: " & e.msg)
  finally:
    client.close()

