  proc testProxy() {.async.} =
    await sleepAsync(500)
    let client = newAsyncHttpClient()
    let resp = await client.get("http://localhost:8089/get?proxy=true")
    echo "Proxy Response Code: ", resp.status
    client.close()

  asyncCheck testProxy()
  waitFor server.serve(Port(8089), proxyHandler)

