proc handlePubSubClient(client: AsyncSocket) {.async.} =
  try:
    while true:
      let line = await client.recvLine()
      if line == "": break

      let parts = line.split(" ", 2)
      if parts.len < 2: continue

      let cmd = parts[0].toUpperAscii()
      let topic = parts[1]

      if cmd == "SUB":
        if not topics.hasKey(topic):
          topics[topic] = @[]
        topics[topic].add(client)
        await client.send("Subscribed to " & topic & "\r\n")
      elif cmd == "PUB" and parts.len == 3:
        let msg = parts[2]
        if topics.hasKey(topic):
          for sub in topics[topic]:
            if sub != client:
               asyncCheck sub.send("MSG " & topic & " " & msg & "\r\n")
        await client.send("Published\r\n")
  except CatchableError:
    discard
  finally:
    for k, v in topics.mpairs:
      let idx = v.find(client)
      if idx >= 0: v.delete(idx)
    client.close()

