proc parseCsvAsync(filePath: string) {.async.} =
  let f = open(filePath, fmRead)
  defer: f.close()
  var buffer = newString(1024)
  var overlap = ""
  var lineCount = 0

  while true:
    let bytesRead = f.readChars(buffer, 0, 1024)
    if bytesRead == 0: break

    let chunk = overlap & buffer[0 ..< bytesRead]
    let lines = chunk.splitLines()

    for i in 0 ..< lines.len - 1:
      if lines[i].len > 0:
        lineCount.inc

    if lines.len > 0:
      overlap = lines[^1]

    await sleepAsync(0)

  if overlap.len > 0: lineCount.inc
  echo "CSV Parsing complete. Total lines: ", lineCount

