proc multiplexStreams(cmd: string) {.async.} =
  let p = startProcess(cmd, options = {poUsePath})
  let outStr = p.outputStream
  let errStr = p.errorStream

  var active = true

  proc pollStream(s: Stream, label: string) {.async.} =
    while active or not s.atEnd():
      if s.atEnd():
        await sleepAsync(10)
        continue
      echo label, ": ", s.readLine()
      await sleepAsync(0)

  let p1 = pollStream(outStr, "[STDOUT]")
  let p2 = pollStream(errStr, "[STDERR]")

  while p.running:
    await sleepAsync(50)

  active = false
  await all(p1, p2)
  p.close()

