proc connectSSE(host: string, port: int, path: string) {.async.} =
  let client = newAsyncSocket()
  await client.connect(host, Port(port))

  let req = "GET " & path & " HTTP/1.1\r\nHost: " & host & "\r\nAccept: text/event-stream\r\n\r\n"
  await client.send(req)

  while true:
    let line = await client.recvLine()
    if line == "" or line == "\r\n": break

  var buffer = ""
  while true:
    let chunk = await client.recv(1024)
    if chunk.len == 0: break
    buffer.add(chunk)

    while true:
      let pos = buffer.find("\n\n")
      if pos == -1: break

      let eventRaw = buffer[0 ..< pos]
      buffer = buffer[pos + 2 .. ^1]

      var eventName = "message"
      var eventData = ""

      for line in eventRaw.splitLines():
        if line.startsWith("event:"):
          eventName = line[6..^1].strip()
        elif line.startsWith("data:"):
          eventData.add(line[5..^1].strip() & "\n")

      echo "SSE Event [", eventName, "]: ", eventData.strip()
  client.close()

