proc downloadResumable(url: string, destPath: string) {.async.} =
  var existingSize = 0
  if fileExists(destPath):
    existingSize = getFileSize(destPath).int

  let client = newAsyncHttpClient()

  if existingSize > 0:
    client.headers = newHttpHeaders([("Range", "bytes=" & $existingSize & "-")])
    echo "Resuming download from byte ", existingSize
  else:
    echo "Starting fresh download..."

  try:
    let resp = await client.request(url, HttpGet)
    if resp.code == Http206 or resp.code == Http200:
      let f = open(destPath, fmAppend)
      defer: f.close()

      while true:
        let (hasData, chunk) = await resp.bodyStream.read()
        if not hasData: break
        f.write(chunk)

      echo "Download completed successfully."
  except CatchableError as e:
    echo "Download interrupted: ", e.msg
  finally:
    client.close()

